    # Identify non-background cells
    non_bg = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != background:
                non_bg.add((r, c))

    # Check which cells cascade diagonally (down-right from bottom values)
    # A cell cascades down-right if: it's non-background AND there's no other non-background
    # cell below it in the same diagonal direction
    bottom_cascade = set()

    # For each non-background cell, check if it's the "bottommost" in its diagonal
    for r, c in non_bg:
        cascades = False
        for k in range(1, max(len(grid), len(grid[0]))):
            nr, nc = r + k, c + k
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if (nr, nc) in non_bg:
                    break
                cascades = True
            else:
                break
        if cascades:
            bottom_cascade.add((r, c))

    # Propagate cascading values down-right
    for r, c in bottom_cascade:
        val = grid[r][c]
        for k in range(1, max(len(grid), len(grid[0]))):
            nr, nc = r + k, c + k
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
